import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"CDS G/H (Day 2) - CephFS- file creation & object-level backtraces","description":"","frontmatter":{"title":"CDS G/H (Day 2) - CephFS- file creation & object-level backtraces","date":"2014-06-26T00:00:00.000Z","updated":"2014-06-26T00:00:00.000Z","tags":["CephFS","文件创建","对象级回溯","Ceph","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_2_-_CephFS_-_file_creation_object-level_backtraces.md","filePath":"posts/2014/CDS_G_H_Day_2_-_CephFS_-_file_creation_object-level_backtraces.md","lastUpdated":1780459816000}'),r={name:"posts/2014/CDS_G_H_Day_2_-_CephFS_-_file_creation_object-level_backtraces.md"};function s(a,l,n,_,p,c){return t(),i("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph 文件系统（CephFS）文件创建与对象级回溯讨论</p><p><strong>会议时间</strong>： 2014-06-26</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议内容</strong>：</p><p><strong>一、主要议题</strong></p><ol><li><p><strong>文件创建和对象级回溯问题</strong>：</p><ul><li>用户 Alexander 投诉客户端回溯信息过多，导致 OSD 集群负载过重。</li><li>讨论了将回溯信息写入元数据池或键值存储的可行性。</li><li>提出将回溯信息作为能力机制的一部分通过客户端进行更新的方案。</li><li>探讨了异步文件创建的可行性，包括如何处理客户端失败和确保文件属性正确。</li><li>讨论了回溯信息的存储方式，包括是否将其存储在元数据池、键值存储或数据池。</li></ul></li><li><p><strong>异步文件创建</strong>：</p><ul><li>讨论了异步文件创建的可行性，包括如何处理客户端失败和确保文件属性正确。</li><li>提出使用未分配的inode队列来实现异步创建的方案。</li></ul></li><li><p><strong>回溯信息存储</strong>：</p><ul><li>讨论了回溯信息的存储方式，包括是否将其存储在元数据池、键值存储或数据池。</li><li>认为将回溯信息存储在数据池中可能更高效，但需要考虑如何处理数据池迁移的情况。</li></ul></li></ol><p><strong>二、决定事项</strong></p><ol><li>将文件创建和对象级回溯问题的解决方案作为单独的工单提交到跟踪器，并优先处理。</li><li>研究异步文件创建的可行性，并评估其性能和可靠性。</li><li>探索回溯信息存储的最佳方案，并考虑数据池迁移的情况。</li></ol><p><strong>三、后续行动计划</strong></p><ol><li>[开发人员] John 将研究异步文件创建的方案，并评估其可行性。</li><li>[开发人员] Greg 将研究回溯信息存储的最佳方案，并考虑数据池迁移的情况。</li><li>[开发人员] Alexander 将将文件创建和对象级回溯问题的解决方案作为单独的工单提交到跟踪器。</li></ol><p><strong>四、关键术语</strong></p><ul><li><strong>CFS</strong>： Ceph 文件系统</li><li><strong>OSD</strong>： 块设备</li><li><strong>MDS</strong>： 元数据服务器</li><li><strong>inode</strong>： 文件系统中的节点，包含文件属性和指针</li><li><strong>back trace</strong>： 回溯信息，用于从inode号查找文件位置</li></ul><p><strong>五、备注</strong></p><ul><li>会议中讨论的方案需要进一步研究和评估，以确保其可行性和性能。</li><li>异步文件创建和回溯信息存储的优化将有助于提高 Ceph 文件系统的性能和可靠性。</li><li>需要考虑将回溯信息存储在数据池中，但需注意数据池迁移的情况。</li><li>考虑使用键值存储来存储回溯信息，以提高效率。</li></ul>',15)])])}const S=e(r,[["render",s]]);export{d as __pageData,S as default};
